import base64,gzip,hashlib,io,json,os,pathlib,tarfile
raw=base64.b64decode('',validate=True)
assert len(raw)==23596 and hashlib.sha256(raw).hexdigest()=='81184084b53b2efce928bf18eedba56ae0f4b8453143d923d9ecd5fccee36fa9'
with gzip.GzipFile(fileobj=io.BytesIO(raw),mode='rb') as stream:
    expanded=stream.read(512*1024+1)
assert len(expanded)<=512*1024
files={}
with tarfile.open(fileobj=io.BytesIO(expanded),mode='r:') as archive:
    for item in archive:
        p=pathlib.PurePosixPath(item.name)
        assert item.isfile() and not p.is_absolute() and '..' not in p.parts and str(p)==item.name
        assert p.parts[0]=='cache-prune-tools-02' and item.name not in files and len(files)<9 and 0<=item.size<=128*1024
        data=archive.extractfile(item).read(128*1024+1)
        assert len(data)==item.size
        files[item.name]=data
assert len(files)==9 and sum(map(len,files.values()))==105808
assert hashlib.sha256(files['cache-prune-tools-02/prune_cache.py']).hexdigest()=='fe09125bd509a73b67b5380857f5ff61a5c69a89d592afcfa1172121418588f5'
assert hashlib.sha256(files['cache-prune-tools-02/plan.json']).hexdigest()=='1179668edde634ffba8307ca35c129652d9df15c0743c76b5bdc4e6fe8f7d62b'
plan=json.loads(files['cache-prune-tools-02/plan.json'])
for item in plan['prior_failed_attempt']['originals'].values():
    data=files[item['path']]
    assert len(data)==item['bytes'] and hashlib.sha256(data).hexdigest()==item['sha256']
root=pathlib.Path('/home/qian/hepta-runtime-optimization-20261106-r34')
assert root.resolve(strict=True)==root and root.stat().st_uid==os.getuid()==1000
assert all(not os.path.lexists(root/n) for n in ('source','target-build','qualification-01','preparation.json','cache-prune-02'))
(root/'cache-prune-tools-02').mkdir(mode=0o700)
for name,data in sorted(files.items()):
    path=root/name
    path.parent.mkdir(parents=True,exist_ok=True,mode=0o700)
    assert path.parent.resolve(strict=True)==path.parent
    with path.open('xb') as stream:
        stream.write(data);stream.flush();os.fsync(stream.fileno())
    assert path.read_bytes()==data
os.execv('/usr/bin/python3',['/usr/bin/python3','-B','-u',str(root/'cache-prune-tools-02/prune_cache.py'),'--plan-sha256','1179668edde634ffba8307ca35c129652d9df15c0743c76b5bdc4e6fe8f7d62b'])
